private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    OuterFaceCirculator circulator = new OuterFaceCirculator(start, dir);
    while (circulator != null && !circulator.equals(stop)) {
        if (predicate.test(circulator.get())) {
            return circulator;
        }
        circulator.move();
    }
    return null;
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    // Initialize the current node to the start node
    Node current = start;
    // Set the counter to 0
    int count = 0;

    // Loop until we reach the stop node or until we find a node that satisfies the predicate
    while (current != stop && !predicate.test(current)) {
        // If the counter is 0, move to the next node in the direction of the outer face
        if (count == 0) {
            current = current.getNextNodeInDirection(dir);
        } else {
            // If the counter is not 0, move to the next node in the opposite direction of the outer face
            current = current.getNextNodeInDirection(1 - dir);
        }
        // Increment the counter
        count++;
    }

