    GraphPath<V,E> path = new GraphPath<>(graph);
    for (E edge : tour) {
        path.addEdge(graph.getEdgeSource(edge), graph.getEdgeTarget(edge));
    }
    return path;
}

private GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    GraphPath<V, E> path = new GraphPath<>();
    List<E> remainingEdges = new ArrayList<>(tour);
    if (!remainingEdges.isEmpty()) {
        E firstEdge = remainingEdges.removeFirst();
        V firstVertex = graph.getEdgeSource(firstEdge);
        path.add(firstEdge);
        remainingEdges.remove(firstEdge);
        while (!remainingEdges.isEmpty()) {
            E nextEdge = remainingEdges.stream()
                    .filter(e -> graph.getEdgeSource(e) == graph.getDestination(path.getLastEdge()))
                    .findFirst()
                    .orElse(remainingEdges.removeFirst());
            path.add(nextEdge);
            remainingEdges.remove(nextEdge);
        }
        if (remainingEdges.isEmpty()) {
            path.add(graph.getEdgeDestination(path.getLastEdge()));
        }
    }
    return path;
}

