private String unescapeId(String input) {
    StringBuilder output = new StringBuilder();
    for (int i = 0, len = input.length(); i < len; i++) {
        char ch = input.charAt(i);
        if (ch == '\\') {
            ch = input.charAt(++i);
            switch (ch) {
                case 'n':
                    output.append('\n');
                    break;
                case 'r':
                    output.append('\r');
                    break;
                case 't':
                    output.append('\t');
                    break;
                case '\\':
                    output.append('\\');
                    break;
                default:
                    output.append('\\').append(ch);
            }
        } else {
