public static void addToClassPath(Vector<URL> cpV, String dir) {
        try {
            File dirObj = new File(dir);
            if (!dirObj.isDirectory() || !dirObj.exists()) {
                throw new IllegalArgumentException("Input string " + dir + " is not a valid directory");
            }
            // Get all jar files in the directory
            File[] jarFiles = dirObj.listFiles(new FilenameFilter() {
                @Override
                public boolean accept(File dir, String name) {
                    return name.endsWith(".jar");
                }
            });
            // Iterate through the jar files and create URL objects
            for (File jarFile : jarFiles) {
                URL url = jarFile.toURI().toURL();
                cpV.add(url);
            }
        } catch (MalformedURLException e) {
            throw new IllegalArgumentException("Input string " + dir + " is not a valid URL");
        }
    }

public static void addToClassPath(Vector<URL> cpV, String dir) throws IOException {
    if (dir == null) {
        throw new IllegalArgumentException("Directory parameter cannot be null");
    }
    File folder = new File(dir);
    if (!folder.isDirectory()) {
        throw new IllegalArgumentException("The specified path is not a directory");
    }
    for (File f : folder.listFiles()) {
        if (f.getName().endsWith(".jar")) {
            cpV.add(f.toURI().toURL());
        }
    }
}

public static void addToClassPath(Vector<URL> cpV, String dir) {
    File directory = new File(dir);
    if (!directory.exists() || !directory.isDirectory()) {
        throw new IllegalArgumentException("Invalid directory: " + dir);
    }
    File[] files = directory.listFiles(new FilenameFilter() {
        @Override
        public boolean accept(File dir, String name) {
            return name.toLowerCase().endsWith(".jar");
        }
    });
    for (File file : files) {
        try {
            cpV.add(file.toURI().toURL());
        } catch (MalformedURLException e) {
            throw new IllegalArgumentException("Invalid URL: " + e.getMessage());
        }
    }
}

public static void addToClassPath(String dir) throws IOException {
    // Get the current classloader
    ClassLoader classLoader = Thread.currentThread().getContextClassLoader();

    // Get the URL of the directory that contains the jar files
    URL dirUrl = new URL(dir);

    // Get the list of files in the directory
    File dirFile = new File(dir);
    File[] files = dirFile.listFiles();

    // Loop through the files and add them to the classpath
    for (File file : files) {
        if (file.isFile() && file.getName().endsWith(".jar")) {
            URL jarUrl = new URL(dirUrl, file.getName());
            URLConnection conn = jarUrl.openConnection();
            conn.setUseCaches(false);
            classLoader.addURL(jarUrl);
        }
    }
}

