public int removeUnusedNodes() {
    int numRemoved = 0;

    // Loop through all nodes in the tree
    for (int i = 0; i < treeSize(); i++) {
        // Get the current node
        Node currentNode = getNodeAt(i);

        // Check if the node is inactive
        if (!currentNode.isActive()) {
            // Remove the node from the tree
            removeNode(currentNode);
            numRemoved++;
        }
    }

    return numRemoved;
}

private void removeUnusedNodes() {
    // Get the root category
    Category root = categoryService.getRootCategory();

    // Iterate through all child categories of the root
    for (Category child : root.getChildCategories()) {

        // Check if the child category is inactive
        if (!child.isActive()) {

            // Remove the child category
            root.removeChildCategory(child.getId());

            // Remove any child categories that are nested under the child category
            for (Category grandchild : child.getChildCategories()) {
                if (!grandchild.isActive()) {
                    child.removeChildCategory(grandchild.getId());
                }
            }
        }
    }
}

