public void abbreviate(final int nameStart, final StringBuffer buf) {

  // Split the name at the nameStart index and take the first letter
  String firstLetter = buf.substring(nameStart).split(" ")[0];

  // Check if the letter is a vowel
  if (firstLetter.equalsIgnoreCase("a") || firstLetter.equalsIgnoreCase("e") || firstLetter.equalsIgnoreCase("i") || firstLetter.equalsIgnoreCase("o") || firstLetter.equalsIgnoreCase("u")) {
    // Vowels remain the same
    buf.append(firstLetter);
  } else {
    // Consonants become asterisks
    buf.append("*");
  }
}

public void abbreviate(String name) {
    if (name == null) {
        throw new NullPointerException("name cannot be null");
    }
    if (name.isEmpty()) {
        return;
    }
    String[] words = name.split(" ");
    String abbr = "";
    for (String word : words) {
        String temp;
        if (word.isEmpty()) {
            temp = "";
        } else if (word.length() == 1) {
            temp = word.toLowerCase();
        } else {
            temp = word.charAt(0);
        }
        abbr += temp;
    }
    buf.append(abbr);
}

public void abbreviate(final int nameStart, final StringBuffer buf) {
    // Get the name substring to abbreviate from the input string
    String name = input.substring(nameStart);

    // Initialize variables for abbreviation
    int length = 0;
    int lastSpace = 0;
    boolean endsWithSpace = false;

    // Iterate through the name characters to check if it ends with a space, and if not, find the last space
    for (int i = nameStart; i < input.length(); i++) {
        if (input.charAt(i) == ' ') {
            endsWithSpace = true;
            break;
        }
        if (input.charAt(i) != ' ' && length - lastSpace < 3) {
            length++;
            lastSpace = i;
        }
    }

    // If the length of the name exceeds the threshold, or it ends with a space, return the original name
    if (length > abbreviationThreshold || endsWithSpace) {
        buf.append(name);
    }

    // Otherwise, return the abbreviated name
    else {
        buf.append(input.substring(nameStart, lastSpace));
    }
}

public static void abbreviate(final String name, final StringBuffer buf) {
    // Check if the input parameters are valid
    if (name == null || buf == null) {
        throw new IllegalArgumentException("Invalid input arguments");
    }

    // Abbreviate the name
    String abbreviation = name.substring(nameStart);
    abbreviation = abbreviation.replaceAll("[^A-Za-z]", "");
    abbreviation = abbreviation.toUpperCase();
    buf.append(abbreviation);
}

public void abbreviate(final int nameStart, final StringBuffer buf) {
    if (nameStart < 0) {
        buf.append("Invalid negative nameStart");
    } else if (buf == null) {
        buf.append("Invalid null buffer");
    } else {
        char c1 = buf.charAt(nameStart);
        char c2 = buf.charAt(nameStart+1);
        if (Character.isLowerCase(c2)) {
            buf.setCharAt(nameStart, Character.toUpperCase(c1));
        }
        buf.setCharAt(nameStart+1, Character.toLowerCase(c2));
    }
}

