  for (int i = 0; i < curMappings.length; i++) {
    String[] curField = curMappings[i];
    boolean hasMatch = false;
    for (int j = 0; j < prevMappings.length; j++) {
      String[] prevField = prevMappings[j];
      if (Arrays.equals(curField, prevField)) {
        hasMatch = true;
