public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    if (file == null || timeRanges == null || timeRanges.isEmpty()) {
        throw new IllegalArgumentException("Invalid input: file or timeRanges is null or empty");
    }

    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();
    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            List<String> parts = parseLine(line);
            if (parts.size() < 7) {
                throw new IllegalArgumentException("Invalid file format: not enough parts in line");
            }

            String startTime = parts.get(0);
            String endTime = parts.get(1);
            String cpuUsage = parts.get(2);
            String memUsage = parts.get(3);
            String threadId = parts.get(4);
            String threadName = parts.get(5);
            String threadState = parts.get(6);

            if (!isInTimeRanges(timeRanges, startTime)) {
                continue;
            }

            ThreadSnapshot threadSnapshot = new ThreadSnapshot(startTime, endTime, cpuUsage, memUsage, threadId, threadName, threadState);
            threadSnapshots.add(threadSnapshot);
        }
    } catch (IOException e) {
        throw new IOException("Error reading file: " + e.getMessage(), e);
    }

    return threadSnapshots;
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {    
        List<ThreadSnapshot> threadSnapshots = new ArrayList<ThreadSnapshot>();    
        long totalElapsedTimeNanos = 0;    
        List<List<ThreadSnapshot>> snapshots = readSnapshotsFromFile(file);    
        for (List<ThreadSnapshot> snapshotsList : snapshots) {  
            long elapsedTimeNanos = snapshotsList.get(snapshotsList.size()-1).getTimestamp() - snapshotsList.get(0).getTimestamp();       
            if(timeRanges.stream().anyMatch(timeRange -> timeRange.isInsideTimestampInterval(snapshotsList.get(0).getTimestamp(), elapsedTimeNanos)))  {                       
                threadSnapshots.addAll(snapshotsList);    
                totalElapsedTimeNanos += elapsedTimeNanos;    
            }    
        }     
        Collections.sort(threadSnapshots, new Comparator<ThreadSnapshot>(){    
            @Override         
            public int compare(ThreadSnapshot o1, ThreadSnapshot o2)  {            return (o2.getTimestamp()).compareTo(o1.getTimestamp());          }      });       
        return threadSnapshots;    }

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) {
    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();
    try (BufferedReader br = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = br.readLine()) != null) {
            ThreadSnapshot snapshot = new ThreadSnapshot(line);
            if (timeRanges.stream().anyMatch(tr -> tr.contains(snapshot.getDuration()))) {
                threadSnapshots.add(snapshot);
            }
        }
        return threadSnapshots;
    } catch (IOException e) {
        e.printStackTrace();
        return null;
    }
