public static List<ThreadSnapshot> getThreadSnapshotsWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
        if (file == null || timeRanges == null) {
            throw new IllegalArgumentException("File and timeRanges must not be null.");
        }
        List<ThreadSnapshot> threadSnapshots = new ArrayList<>();
        try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
            String line = null;
            while ((line = reader.readLine()) != null) {
                ProfileAnalyzeTimeRange timeRange = timeRanges.stream()
                        .filter(tr -> tr.getStartTime() <= line.getStartTime() && line.getEndTime() <= tr.getEndTime())
                        .findFirst()
                        .orElseThrow(() -> new IllegalArgumentException("No time range found for " + line));
                ThreadSnapshot snapshot = new ThreadSnapshot();
                snapshot.setStatus(line.getStatus());
                snapshot.setStartTime(line.getStartTime());
                snapshot.setEndTime(line.getEndTime());
                if (line.getStackTrace() != null) {
                    snapshot.setStackTrace(line.getStackTrace());
                }
                threadSnapshots.add(snapshot);
            }
        }
        return threadSnapshots;
